def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    tracks = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            cells = set()

            if color == 1:
                # Two steps right, then one step up to the new 1.
                for p in [(r, c), (r, c + 1), (r, c + 2), (r - 1, c + 2)]:
                    if 0 <= p[0] < h and 0 <= p[1] < w:
                        cells.add(p)
                for p in [(r, c + 1), (r, c + 2)]:
                    if 0 <= p[0] < h and 0 <= p[1] < w:
                        out[p[0]][p[1]] = 5
                if 0 <= r - 1 < h and 0 <= c + 2 < w:
                    out[r - 1][c + 2] = 1

            elif color == 2:
                for k in range(1, 5):
                    cc = c - k
                    if 0 <= cc < w:
                        cells.add((r, cc))
                        out[r][cc] = 2 if k == 4 else 5
                cells.add((r, c))

            elif color == 3:
                cells.add((r, c))
                for k in range(1, 4):
                    rr = r + k
                    if 0 <= rr < h:
                        cells.add((rr, c))
                        out[rr][c] = 3 if k == 3 else 5

            elif color == 6:
                cells.add((r, c))
                for k in range(1, 7):
                    rr = r - k
                    if 0 <= rr < h:
                        cells.add((rr, c))
                        out[rr][c] = 6 if k == 6 else 5

            else:
                continue

            tracks.append(cells)

    # Intersections are marked 4 and continue diagonally down-left.
    for i in range(len(tracks)):
        for j in range(i + 1, len(tracks)):
            for r, c in tracks[i] & tracks[j]:
                out[r][c] = 4
                rr, cc = r + 1, c - 1
                while rr < h and cc >= 0:
                    out[rr][cc] = 4
                    rr += 1
                    cc -= 1

    return out
